/*
 * Standalone logic-equivalence test for CVE-2014-8884 backport.
 *
 * This does NOT build the kernel driver. It mirrors the exact buffer
 * arithmetic of ttusbdecfe_dvbs_diseqc_send_master_cmd() so the security
 * invariant can be exercised at runtime in an environment without make,
 * .config or generated kernel headers.
 *
 * Reported by: model-led validation. The guarded expression is copied
 * verbatim from the candidate patch.
 */
#include <stdio.h>
#include <string.h>

#define EINVAL 22
typedef unsigned char u8;

struct dvb_diseqc_master_cmd {
	u8 msg[6];
	u8 msg_len;
};

struct frame {
	u8 b[10];
	u8 tail[4]; /* stands in for adjacent stack memory */
};

static int copy_like_driver(struct dvb_diseqc_master_cmd *cmd, int guarded,
			    struct frame *f)
{
	u8 b[] = { 0x00, 0xff, 0x00, 0x00,
		   0x00, 0x00, 0x00, 0x00,
		   0x00, 0x00 };

	memset(f, 0, sizeof(*f));
	memcpy(f->b, b, sizeof(b));
	memset(f->tail, 0xAA, sizeof(f->tail));

	if (guarded) {
		if (cmd->msg_len > sizeof(b) - 4)
			return -EINVAL;
	}

	/* The driver copies into its own b[10]; use the frame so an
	 * over-long copy is observable deterministically. */
	memcpy(&f->b[4], cmd->msg, cmd->msg_len);
	return 0;
}

static int tail_intact(const struct frame *f)
{
	int i;
	for (i = 0; i < 4; i++)
		if (f->tail[i] != 0xAA)
			return 0;
	return 1;
}

int main(void)
{
	struct dvb_diseqc_master_cmd cmd;
	struct frame f;
	int rc, failures = 0;

	memset(cmd.msg, 0x5A, sizeof(cmd.msg));

	/* Positive path: msg_len == 6 (valid maximum) must proceed. */
	cmd.msg_len = 6;
	rc = copy_like_driver(&cmd, 1, &f);
	printf("guarded msg_len=6: rc=%d tail_intact=%d\n", rc, tail_intact(&f));
	if (rc != 0 || !tail_intact(&f))
		failures++;

	/* Negative path: msg_len == 8 must be rejected before the copy. */
	cmd.msg_len = 8;
	rc = copy_like_driver(&cmd, 1, &f);
	printf("guarded msg_len=8: rc=%d tail_intact=%d\n", rc, tail_intact(&f));
	if (rc != -EINVAL || !tail_intact(&f))
		failures++;

	/* Control: without the guard the same input overflows. */
	cmd.msg_len = 8;
	rc = copy_like_driver(&cmd, 0, &f);
	printf("unguarded msg_len=8: rc=%d tail_intact=%d (overflow reproduced)\n",
	       rc, tail_intact(&f));
	if (tail_intact(&f))
		failures++;

	if (failures) {
		printf("RESULT: FAIL (%d)\n", failures);
		return 1;
	}
	printf("RESULT: PASS\n");
	return 0;
}

